import{_ as d,o as a,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const b=JSON.parse('{"title":"🍜 亦庄美食地图：东北人视角的宝藏小店","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/culture/yizhuang-food-map.md","filePath":"topics/culture/yizhuang-food-map.md"}'),o={name:"topics/culture/yizhuang-food-map.md"};function h(u,t,i,l,n,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="🍜-亦庄美食地图-东北人视角的宝藏小店" tabindex="-1">🍜 亦庄美食地图：东北人视角的宝藏小店 <a class="header-anchor" href="#🍜-亦庄美食地图-东北人视角的宝藏小店" aria-label="Permalink to &quot;🍜 亦庄美食地图：东北人视角的宝藏小店&quot;">​</a></h1><p>一位在亦庄深耕十余年的&quot;老吃货&quot;，以东北人的口味偏好，为你盘点两大核心商圈的美食。这份清单不仅有经典老店，还有新晋网红，更附带了独家的&quot;美食搭配&quot;秘诀。</p><hr><h2 id="🏬-上海沙龙商圈-经典老店集结地" tabindex="-1">🏬 上海沙龙商圈：经典老店集结地 <a class="header-anchor" href="#🏬-上海沙龙商圈-经典老店集结地" aria-label="Permalink to &quot;🏬 上海沙龙商圈：经典老店集结地&quot;">​</a></h2><p>上海沙龙是亦庄最早的商业中心，聚集了许多十年以上的老店，是寻找&quot;老味道&quot;的绝佳去处。</p><table tabindex="0"><thead><tr><th>推荐店铺</th><th>招牌菜/特色</th><th>搭配建议</th></tr></thead><tbody><tr><td>大理米线</td><td>粗米线，搭配肥牛、肥羊、鱼丸，麻油和辣椒油是灵魂</td><td>冰红茶</td></tr><tr><td>单县羊汤</td><td>奶白色的汤，配羊油辣椒和软于小饼</td><td>-</td></tr><tr><td>王记麻辣烫</td><td>东北传统黏糊麻辣烫，炸串也不错</td><td>冰红茶</td></tr><tr><td>张记黄焖鸡米饭</td><td>视频作者力荐！&quot;从108斤吃到148斤&quot;的秘诀</td><td>可乐</td></tr></tbody></table><hr><h2 id="🌳-林肯公园商圈-新旧融合的美食地" tabindex="-1">🌳 林肯公园商圈：新旧融合的美食地 <a class="header-anchor" href="#🌳-林肯公园商圈-新旧融合的美食地" aria-label="Permalink to &quot;🌳 林肯公园商圈：新旧融合的美食地&quot;">​</a></h2><p>林肯公园商圈既有老牌劲旅，也有后起之秀，选择更加多元。</p><table tabindex="0"><thead><tr><th>推荐店铺</th><th>招牌菜/特色</th><th>搭配建议</th></tr></thead><tbody><tr><td>油泼面 (红牌)</td><td>三合一宽油泼面，多辣</td><td>荔枝味大窑</td></tr><tr><td>柳州肥姨妈螺蛳粉</td><td>味道正宗，但&quot;杀伤力&quot;强，建议带换洗衣物</td><td>-</td></tr><tr><td>福林饺子馆</td><td>西葫芦鸡蛋馅饺子，&quot;亦庄最好吃的东北菜&quot;</td><td>-</td></tr><tr><td>福和牛烤肉自助</td><td>性价比高，啤酒免费，主食意外地好吃</td><td>-</td></tr><tr><td>何小敏串串</td><td>新晋网红，天天排队</td><td>-</td></tr><tr><td>韩式牛肉火锅</td><td>点单牛胸口，让服务员帮忙调蘸料</td><td>-</td></tr><tr><td>下酒烤串</td><td>有菠萝烤肉，晚上有驻唱</td><td>-</td></tr></tbody></table><hr><h2 id="💡-独家美食搭配公式" tabindex="-1">💡 独家美食搭配公式 <a class="header-anchor" href="#💡-独家美食搭配公式" aria-label="Permalink to &quot;💡 独家美食搭配公式&quot;">​</a></h2><blockquote><p>视频中的&quot;知识点&quot;，据说&quot;以后要考&quot;。</p></blockquote><table tabindex="0"><thead><tr><th>美食</th><th>最佳拍档</th></tr></thead><tbody><tr><td>黄焖鸡米饭</td><td>可乐</td></tr><tr><td>麻辣烫 / 米线</td><td>冰红茶</td></tr><tr><td>油泼面</td><td>荔枝味大窑</td></tr></tbody></table>',14)])])}const p=d(o,[["render",h]]);export{b as __pageData,p as default};
